import {
  BaseSheet,
  FillRangeOperation,
  InsertRowOperation,
  Operation,
  RemoveRowOperation,
  Sheet,
  UpdateCellOperation,
} from '@bzl/sheet-js';
import { initialDoc } from '../utils';
import { SheetOTType } from '../../src';
import { describe, expect, beforeEach, test, afterEach } from 'vitest';

describe.concurrent('left side to remove-row, right side to:', () => {
  let doc1: Omit<BaseSheet, 'apply'>;
  let doc2: Omit<BaseSheet, 'apply'>;
  const op1: RemoveRowOperation = {
    type: 'remove-row',
    at: 2,
    count: 2,
    id: '1',
  };
  let op2: Operation;

  beforeEach(() => {
    doc1 = initialDoc() as Sheet;
    doc2 = initialDoc() as Sheet;
  });

  afterEach(() => {
    const [op12, op21] = SheetOTType.xTransformMxN([op1], [op2], 'left');
    console.log('op12,', op12);
    console.log('op21,', op21);

    doc1 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op1) as BaseSheet, op21);
    doc2 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op2) as BaseSheet, op12);
    console.log('doc1,', doc1);
    console.log('doc2,', doc2);
    expect(doc1).toStrictEqual(doc2);
  });

  describe('update-cell', () => {
    test('at before', () => {
      op2 = {
        type: 'update-cell',
        at: [op1.at - 1, 0],
        newV: null,
        oldV: {
          value: 2,
        },
        id: '1',
      } as UpdateCellOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'update-cell',
        at: [op1.at + 1, 0],
        newV: null,
        oldV: {
          value: 2,
        },
        id: '1',
      } as UpdateCellOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'update-cell',
        at: [op1.at, 0],
        newV: {
          value: 4,
        },
        oldV: {
          value: 2,
        },
        id: '1',
      } as UpdateCellOperation;
    });
  });

  describe('insert-row', () => {
    test('at before', () => {
      op2 = {
        type: 'insert-row',
        at: op1.at - 2,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
    test('at before with intersection', () => {
      op2 = {
        type: 'insert-row',
        at: op1.at - 1,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'insert-row',
        at: op1.at + 1,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'insert-row',
        at: op1.at,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
  });

  describe('remove-row', () => {
    test('at before', () => {
      op2 = {
        type: 'remove-row',
        at: op1.at - 2,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at before with intersection', () => {
      op2 = {
        type: 'remove-row',
        at: op1.at - 1,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-row',
        at: op1.at + 1,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'remove-row',
        at: op1.at,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
  });

  describe.concurrent('fill-range', () => {
    test('at before', () => {
      op2 = {
        type: 'fill-range',
        range: [0, op1.at - 2, 10, op1.at - 1],
        fillBy: 'style',
        style: {
          background: '#FAE1EB',
        },
        id: '1',
      } as FillRangeOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'fill-range',
        range: [0, op1.at + 1, 10, op1.at + 10],
        fillBy: 'style',
        style: {
          background: '#FAE1EB',
        },
        id: '1',
      } as FillRangeOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'fill-range',
        range: [0, op1.at, 10, op1.at + 10],
        fillBy: 'style',
        style: {
          background: '#FAE1EB',
        },
        id: '1',
      } as FillRangeOperation;
    });
  });
});
